import {
  Children,
  cloneElement,
  type CSSProperties,
  type ElementType,
  type HTMLAttributes,
  isValidElement,
  type ReactElement,
  type ReactNode,
} from "react";
import { type AnimationName, type AnimationOptions, animationVars } from "../animation/presets";
import { cx } from "../utils/cx";

export type StaggerProps = AnimationOptions & {
  /** The preset every child plays. Default `fade-up`. */
  animation?: AnimationName;
  /** Milliseconds before the first child. */
  start?: number;
  /** Children are cloned with the animation attributes; text and fragments pass through. */
  children: ReactNode;
};

/**
 * Plays one preset on each child in turn: `<Stagger animation="fade-up" step={60}><Card/><Card/></Stagger>`. It adds
 * `data-hm-anim` and an index to each element child (no wrapper), so it works in server components.
 */
export function Stagger({ animation = "fade-up", start = 0, children, step, ...options }: StaggerProps) {
  const vars = animationVars({ ...options, step, delay: options.delay ?? (start ? start : undefined) });
  let i = 0;
  return (
    <>
      {Children.map(children, (child) => {
        if (!isValidElement(child)) return child;
        const el = child as ReactElement<{ style?: CSSProperties }>;
        const index = i++;
        return cloneElement(el, {
          "data-hm-anim": animation,
          style: { ...vars, "--hm-i": index, ...el.props.style } as CSSProperties,
        } as Record<string, unknown>);
      })}
    </>
  );
}

export type TextRevealProps = AnimationOptions &
  Omit<HTMLAttributes<HTMLElement>, "children"> & {
    /** The text to reveal. */
    text: string;
    /** Split into `word`s (default) or `char`acters. */
    by?: "word" | "char";
    animation?: AnimationName;
    as?: ElementType;
  };

/**
 * Reveals text a word or letter at a time. The full text is the accessible name; the pieces are hidden from assistive
 * technology. Server-compatible.
 */
export function TextReveal({
  text,
  by = "word",
  animation = by === "char" ? "letter-in" : "fade-up",
  as: As = "span",
  step,
  className,
  style,
  duration,
  delay,
  easing,
  count,
  direction,
  distance,
  ...rest
}: TextRevealProps) {
  const pieces = by === "char" ? Array.from(text) : text.split(/(\s+)/);
  const vars = animationVars({
    duration,
    delay,
    easing,
    count,
    direction,
    distance,
    step: step ?? (by === "char" ? 28 : 70),
  });
  let i = 0;
  return (
    <As {...rest} className={cx("hm-text-reveal", className)} style={{ ...vars, ...style }}>
      <span className="hm-sr-only">{text}</span>
      <span aria-hidden="true">
        {pieces.map((p, k) =>
          /^\s+$/.test(p) ? (
            <span key={k}>{p}</span>
          ) : (
            <span
              key={k}
              className="hm-text-reveal-piece"
              data-hm-anim={animation}
              style={{ "--hm-i": i++ } as CSSProperties}
            >
              {p === " " ? "\u00a0" : p}
            </span>
          ),
        )}
      </span>
    </As>
  );
}

export type MarqueeProps = Omit<HTMLAttributes<HTMLDivElement>, "children"> & {
  children: ReactNode;
  /** Seconds for one full loop. Default 30. */
  duration?: number;
  reverse?: boolean;
  /** Stop while hovered or focused. Default true. */
  pauseOnHover?: boolean;
  /** Space between items, a spacing step or CSS length. */
  gap?: string;
};

/**
 * A row of content that scrolls endlessly (logos, quotes, tags). The content is repeated once for a seamless loop; the
 * copy is hidden from assistive technology. Stops under reduced motion. Server-compatible.
 */
export function Marquee({
  children,
  duration = 30,
  reverse,
  pauseOnHover = true,
  gap,
  className,
  style,
  ...rest
}: MarqueeProps) {
  return (
    <div
      {...rest}
      className={cx("hm-marquee", className)}
      data-reverse={reverse ? "" : undefined}
      data-pause={pauseOnHover ? "" : undefined}
      style={{ "--hm-marquee-duration": `${duration}s`, "--hm-marquee-gap": gap, ...style } as CSSProperties}
    >
      <div className="hm-marquee-track">
        <div className="hm-marquee-group">{children}</div>
        <div className="hm-marquee-group" aria-hidden="true">
          {children}
        </div>
      </div>
    </div>
  );
}
